'use client';

import * as React from 'react';
import {
  motion,
  spring,
  useMotionValue,
  type HTMLMotionProps,
  type Transition,
} from 'motion/react';

import {
  motionTokens,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from './bottom-navigation-motion';
import { animate as animateStyles } from 'motion/mini';
import { useControlledState } from './bottom-navigation-use-controlled-state';
import { getStrictContext } from './bottom-navigation-strict-context';
import {
  Highlight,
  HighlightItem,
  type HighlightItemProps,
  type HighlightProps,
} from './bottom-navigation-highlight';
import { Slot, type WithAsChild } from './bottom-navigation-slot';
import { SCALE_SPRING, TAP_SCALE } from './bottom-navigation-button';

const HIGHLIGHT_TRANSITION: Transition = motionTokens.spring.selection;
const SCROLL_TRANSITION: Transition = motionTokens.spring.slide;
const FADE_TRANSITION: Transition = motionTokens.transition.fade;
const LABEL_TRANSITION: Transition = motionTokens.spring.selection;
const INSTANT: Transition = { duration: 0 };

// Scrolled less than this, the bar stays as it is.
const SCROLL_THRESHOLD = 6;
// Gap kept between the hidden bar and the edge it slides past.
const HIDDEN_GAP = 8;

type BottomNavigationScrollBehavior = 'none' | 'hide' | 'minimize';

type BottomNavigationContextType = {
  activeValue: string | undefined;
  handleValueChange: (value: string) => void;
  minimized: boolean;
  scrollBehavior: BottomNavigationScrollBehavior;
  scrollTransition: Transition;
};

const [BottomNavigationProvider, useBottomNavigation] =
  getStrictContext<BottomNavigationContextType>('BottomNavigationContext');

const [BottomNavigationItemProvider, useBottomNavigationItem] =
  getStrictContext<{ isActive: boolean }>('BottomNavigationItemContext');

type ScrollTarget = React.RefObject<HTMLElement | null>;

type BottomNavigationProps = Omit<
  HTMLMotionProps<'nav'>,
  'onValueChange' | 'defaultValue'
> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  scrollBehavior?: BottomNavigationScrollBehavior;
  scrollContainer?: ScrollTarget;
  transition?: Transition;
};

function BottomNavigation(props: BottomNavigationProps) {
  return (
    <ReducedMotionConfig>
      <BottomNavigationRoot {...props} />
    </ReducedMotionConfig>
  );
}

function scrollTopOf(target: HTMLElement | Window) {
  return target instanceof Window ? target.scrollY : target.scrollTop;
}

const ACCESSORY = '[data-slot="bottom-navigation-accessory"]';

function keyboardFocus(target: EventTarget) {
  return target instanceof Element && target.matches(':focus-visible');
}

function inAccessory(target: EventTarget) {
  return target instanceof Element && !!target.closest(ACCESSORY);
}

function BottomNavigationRoot({
  ref,
  value,
  defaultValue,
  onValueChange,
  scrollBehavior = 'none',
  scrollContainer,
  transition,
  onFocusCapture,
  onClick,
  style,
  ...props
}: BottomNavigationProps) {
  const [activeValue, setActiveValue] = useControlledState<string | undefined>({
    value,
    defaultValue,
    onChange: onValueChange as (value: string | undefined) => void,
  });
  const reduce = useShouldReduceMotion();
  const slide = useTempoTransition(SCROLL_TRANSITION);
  const fade = useTempoTransition(FADE_TRANSITION);
  const scrollTransition = transition ?? (reduce ? INSTANT : slide);

  const localRef = React.useRef<HTMLElement | null>(null);
  React.useImperativeHandle(ref, () => localRef.current as HTMLElement);

  const [collapsed, setCollapsed] = React.useState(false);
  const hidden = collapsed && scrollBehavior === 'hide';
  const minimized = collapsed && scrollBehavior === 'minimize';
  const y = useMotionValue(0);
  const [offset, setOffset] = React.useState(0);

  const collapse = React.useCallback(() => {
    const nav = localRef.current;
    if (!nav) return;
    if (scrollBehavior === 'hide') {
      const rect = nav.getBoundingClientRect();
      const edge =
        scrollContainer?.current?.getBoundingClientRect().bottom ??
        window.innerHeight;
      setOffset(edge - (rect.top - y.get()) + HIDDEN_GAP);
    }
    setCollapsed(true);
  }, [scrollBehavior, scrollContainer, y]);

  React.useEffect(() => {
    setCollapsed(false);
    if (scrollBehavior === 'none') return;
    const target: HTMLElement | Window = scrollContainer?.current ?? window;
    let last = scrollTopOf(target);
    const onScroll = () => {
      const top = scrollTopOf(target);
      const delta = top - last;
      if (top <= 0) {
        setCollapsed(false);
        last = top;
        return;
      }
      if (Math.abs(delta) < SCROLL_THRESHOLD) return;
      if (delta > 0) collapse();
      else setCollapsed(false);
      last = top;
    };
    target.addEventListener('scroll', onScroll, { passive: true });
    return () => target.removeEventListener('scroll', onScroll);
  }, [scrollBehavior, scrollContainer, collapse]);

  const handleValueChange = React.useCallback(
    (next: string) => {
      setCollapsed(false);
      setActiveValue(next);
    },
    [setActiveValue],
  );

  const context = React.useMemo(
    () => ({
      activeValue,
      handleValueChange,
      minimized,
      scrollBehavior,
      scrollTransition,
    }),
    [
      activeValue,
      handleValueChange,
      minimized,
      scrollBehavior,
      scrollTransition,
    ],
  );

  return (
    <BottomNavigationProvider value={context}>
      <motion.nav
        ref={localRef}
        data-slot="bottom-navigation"
        data-hidden={hidden ? '' : undefined}
        data-minimized={minimized ? '' : undefined}
        style={{
          y: reduce ? 0 : y,
          pointerEvents: hidden ? 'none' : undefined,
          ...style,
        }}
        initial={false}
        animate={
          reduce
            ? { opacity: hidden ? 0 : 1 }
            : { y: hidden ? offset : 0, opacity: 1 }
        }
        transition={reduce ? (transition ?? fade) : scrollTransition}
        onFocusCapture={(event: React.FocusEvent<HTMLElement>) => {
          onFocusCapture?.(event);
          // A press focuses too: its click grows the bar, with its selection.
          if (keyboardFocus(event.target) && !inAccessory(event.target))
            setCollapsed(false);
        }}
        onClick={(event: React.MouseEvent<HTMLElement>) => {
          onClick?.(event);
          if (!inAccessory(event.target)) setCollapsed(false);
        }}
        {...props}
      />
    </BottomNavigationProvider>
  );
}

type BottomNavigationHighlightProps = Omit<
  HighlightProps,
  'controlledItems' | 'value'
>;

function BottomNavigationHighlight({
  transition,
  ...props
}: BottomNavigationHighlightProps) {
  const { activeValue } = useBottomNavigation();
  return (
    <Highlight
      data-slot="bottom-navigation-highlight"
      controlledItems
      value={activeValue ?? null}
      transition={transition ?? HIGHLIGHT_TRANSITION}
      click={false}
      {...props}
    />
  );
}

type BottomNavigationHighlightItemProps = HighlightItemProps & {
  value: string;
};

function BottomNavigationHighlightItem(
  props: BottomNavigationHighlightItemProps,
) {
  return (
    <HighlightItem data-slot="bottom-navigation-highlight-item" {...props} />
  );
}

type BottomNavigationItemProps = WithAsChild<
  HTMLMotionProps<'a'> & {
    value: string;
    tapScale?: number;
  }
>;

const BOX = [
  'width',
  'height',
  'paddingTop',
  'paddingRight',
  'paddingBottom',
  'paddingLeft',
] as const;

type Size = number[];

const sizeOf = (el: HTMLElement): Size => {
  const style = getComputedStyle(el);
  return BOX.map((key) => parseFloat(style[key]));
};

const clearBox = (el: HTMLElement) => {
  for (const key of BOX) el.style[key] = '';
};

const LABEL = '[data-slot="bottom-navigation-label"]';

// The element's size once the labels in it have opened or folded.
// Under its icon, a label folds its height; beside it, its width.
const isBelow = (label: Element) =>
  !!label.parentElement &&
  getComputedStyle(label.parentElement).flexDirection.startsWith('column');

const settledSizeOf = (el: HTMLElement): Size => {
  const labels = [...el.querySelectorAll<HTMLElement>(LABEL)];
  const saved = labels.map(({ style }) => [style.width, style.height] as const);
  for (const label of labels) {
    const folded = 'folded' in label.dataset ? '0px' : 'auto';
    label.style.width = isBelow(label) ? 'auto' : folded;
    label.style.height = isBelow(label) ? folded : 'auto';
  }
  const size = sizeOf(el);
  labels.forEach(({ style }, index) => {
    [style.width, style.height] = saved[index]!;
  });
  return size;
};

// When the bar minimizes or grows back, the element eases from its last size
// and padding to the ones its CSS gives it in the new state.
function useMorph(
  element: React.RefObject<HTMLElement | null>,
  minimized: boolean,
  transition: Transition,
  selected?: boolean,
) {
  const reduce = useShouldReduceMotion();
  const sizeRef = React.useRef<Size | null>(null);
  const controlsRef = React.useRef<ReturnType<typeof animateStyles> | null>(
    null,
  );
  const minimizedRef = React.useRef(minimized);
  const selectedRef = React.useRef(selected);

  React.useLayoutEffect(() => {
    const el = element.current;
    if (!el) return;
    sizeRef.current = sizeOf(el);
    const observer = new ResizeObserver(() => {
      if (!controlsRef.current) sizeRef.current = sizeOf(el);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [element]);

  React.useLayoutEffect(() => {
    const el = element.current;
    const reselected = selected !== selectedRef.current;
    selectedRef.current = selected;
    // Selected while it eases, it heads for its new size instead.
    if (
      !el ||
      (minimized === minimizedRef.current &&
        !(reselected && controlsRef.current))
    )
      return;
    minimizedRef.current = minimized;
    const from = controlsRef.current ? sizeOf(el) : sizeRef.current;
    controlsRef.current?.stop();
    controlsRef.current = null;
    clearBox(el);
    const to = settledSizeOf(el);
    sizeRef.current = to;
    if (reduce || !from || from.every((value, index) => value === to[index]))
      return;
    const controls = animateStyles(
      el,
      {
        ...Object.fromEntries(
          BOX.map((key, index) => [
            key,
            [`${from[index]}px`, `${to[index]}px`],
          ]),
        ),
      },
      transition.type === 'spring'
        ? { ...transition, type: spring }
        : transition,
    );
    controlsRef.current = controls;
    controls.then(() => {
      if (controlsRef.current !== controls) return;
      controlsRef.current = null;
      clearBox(el);
    });
  }, [element, minimized, selected, reduce, transition]);
}

function BottomNavigationItem({
  ref,
  value,
  tapScale = TAP_SCALE,
  asChild = false,
  transition,
  onClick,
  ...props
}: BottomNavigationItemProps) {
  const { activeValue, handleValueChange, minimized, scrollTransition } =
    useBottomNavigation();
  const reduce = useShouldReduceMotion();
  const press = useTempoTransition(SCALE_SPRING);
  const isActive = activeValue === value;
  const Component = asChild ? Slot : motion.a;

  const localRef = React.useRef<HTMLAnchorElement | null>(null);
  React.useImperativeHandle(ref, () => localRef.current as HTMLAnchorElement);
  useMorph(localRef, minimized, scrollTransition, isActive);

  return (
    <BottomNavigationItemProvider value={{ isActive }}>
      <Component
        ref={localRef}
        data-slot="bottom-navigation-item"
        data-state={isActive ? 'active' : 'inactive'}
        data-minimized={minimized ? '' : undefined}
        aria-current={isActive ? 'page' : undefined}
        initial={reduce ? undefined : { transform: 'scale(1)' }}
        whileTap={reduce ? undefined : { transform: `scale(${tapScale})` }}
        transition={transition ?? press}
        {...props}
        onClick={(event: React.MouseEvent<HTMLAnchorElement>) => {
          onClick?.(event);
          if (!event.defaultPrevented) handleValueChange(value);
        }}
      />
    </BottomNavigationItemProvider>
  );
}

type BottomNavigationLabelShow = 'always' | 'active';

type BottomNavigationLabelProps = Omit<HTMLMotionProps<'span'>, 'children'> & {
  children?: React.ReactNode;
  show?: BottomNavigationLabelShow;
};

// Opens out of a blur and folds away with its room: when the bar minimizes,
// and with `show="active"`, when its item isn't selected.
function BottomNavigationLabel({
  ref,
  show = 'always',
  transition,
  className,
  style,
  children,
  ...props
}: BottomNavigationLabelProps) {
  const { minimized, scrollTransition } = useBottomNavigation();
  const { isActive } = useBottomNavigationItem();
  const reduce = useShouldReduceMotion();
  const fade = useTempoTransition(FADE_TRANSITION);
  const select = useTempoTransition(LABEL_TRANSITION);
  const folded = minimized || (show === 'active' && !isActive);
  const localRef = React.useRef<HTMLSpanElement | null>(null);
  React.useImperativeHandle(ref, () => localRef.current as HTMLSpanElement);
  const [below, setBelow] = React.useState(false);
  React.useLayoutEffect(() => {
    if (localRef.current) setBelow(isBelow(localRef.current));
  }, []);
  // Opened or folded by the bar, it moves with the items' sizes.
  const minimizedRef = React.useRef(minimized);
  const byBar = minimizedRef.current !== minimized || show === 'always';
  React.useLayoutEffect(() => {
    minimizedRef.current = minimized;
  }, [minimized]);
  const size = transition ?? (byBar ? scrollTransition : select);
  // Beside its icon, it fades with its width; below it, out of the way first.
  const look =
    show === 'active'
      ? size
      : folded
        ? { ...fade, duration: (fade.duration ?? 0.2) / 2 }
        : fade;

  return (
    <motion.span
      ref={localRef}
      data-slot="bottom-navigation-label"
      data-folded={folded ? '' : undefined}
      style={{
        display: 'inline-flex',
        justifyContent: below ? 'center' : 'flex-start',
        flexShrink: 0,
        overflow: 'clip',
        whiteSpace: 'nowrap',
        ...style,
      }}
      initial={false}
      animate={
        folded
          ? {
              width: below ? 'auto' : 0,
              height: below ? 0 : 'auto',
              opacity: 0,
              filter: 'blur(4px)',
            }
          : { width: 'auto', height: 'auto', opacity: 1, filter: 'blur(0px)' }
      }
      transition={reduce ? INSTANT : { ...size, opacity: look, filter: look }}
      {...props}
    >
      <span className={className} style={{ display: 'inline-flex' }}>
        {children}
      </span>
    </motion.span>
  );
}

type BottomNavigationAccessoryProps = HTMLMotionProps<'div'>;

function BottomNavigationAccessory({
  ref,
  ...props
}: BottomNavigationAccessoryProps) {
  const { minimized, scrollTransition } = useBottomNavigation();
  const localRef = React.useRef<HTMLDivElement | null>(null);
  React.useImperativeHandle(ref, () => localRef.current as HTMLDivElement);
  useMorph(localRef, minimized, scrollTransition);

  return (
    <motion.div
      ref={localRef}
      data-slot="bottom-navigation-accessory"
      data-minimized={minimized ? '' : undefined}
      {...props}
    />
  );
}

export {
  BottomNavigation,
  BottomNavigationHighlight,
  BottomNavigationHighlightItem,
  BottomNavigationItem,
  BottomNavigationLabel,
  BottomNavigationAccessory,
  useBottomNavigation,
  type BottomNavigationProps,
  type BottomNavigationLabelProps,
  type BottomNavigationLabelShow,
  type BottomNavigationAccessoryProps,
  type BottomNavigationScrollBehavior,
  type BottomNavigationHighlightProps,
  type BottomNavigationHighlightItemProps,
  type BottomNavigationItemProps,
};

'use client';

import * as React from 'react';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  MotionConfigContext,
  spring as springGenerator,
  type Transition,
} from 'motion/react';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
  stack: 0.03,
};

function createMotionTokens(tempo = 1) {
  const pace = <T extends Record<string, Transition>>(set: T): T =>
    tempo === 1
      ? set
      : (Object.fromEntries(
          Object.entries(set).map(([role, value]) => [
            role,
            scaleTransition(value, tempo),
          ]),
        ) as T);

  return {
    tempo,
    ease,
    scale,
    blur,
    rotate,
    shift,
    stagger:
      tempo === 1
        ? stagger
        : (Object.fromEntries(
            Object.entries(stagger).map(([role, delay]) => [
              role,
              delay * tempo,
            ]),
          ) as typeof stagger),
    spring: pace(spring),
    transition: pace(transition),
  } as const;
}

type MotionTokens = ReturnType<typeof createMotionTokens>;

const motionTokens: MotionTokens = createMotionTokens();

const MotionTokensContext = React.createContext<MotionTokens>(motionTokens);

const TIME_KEYS = [
  'duration',
  'visualDuration',
  'delay',
  'repeatDelay',
  'delayChildren',
];

function scaleTransition<T extends Transition | undefined>(
  transition: T,
  tempo: number,
): T {
  if (!transition || tempo === 1 || typeof transition !== 'object')
    return transition;
  const scaled: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(transition)) {
    if (typeof value === 'number' && TIME_KEYS.includes(key))
      scaled[key] = value * tempo;
    else if (typeof value === 'number' && key === 'stiffness')
      scaled[key] = value / (tempo * tempo);
    else if (typeof value === 'number' && key === 'damping')
      scaled[key] = value / tempo;
    else if (value && typeof value === 'object' && !Array.isArray(value))
      scaled[key] = scaleTransition(value as Transition, tempo);
    else scaled[key] = value;
  }
  return scaled as T;
}

function useTempoTransition<T extends Transition | undefined>(
  transition: T,
): T {
  const { tempo } = React.use(MotionTokensContext);
  return scaleTransition(transition, tempo);
}

function useMotionTokens(): MotionTokens {
  return React.use(MotionTokensContext);
}

type CheckAnimation = 'draw' | 'pop';

const CheckAnimationContext = React.createContext<CheckAnimation>('draw');

function useCheckAnimation(own?: CheckAnimation): CheckAnimation {
  const inherited = React.use(CheckAnimationContext);
  return own ?? inherited;
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

type ReducedMotion = 'user' | 'never' | 'always';

const ReducedMotionContext = React.createContext<ReducedMotion>('user');

function useReducedMotionSetting(): ReducedMotion {
  const own = React.use(ReducedMotionContext);
  const { reducedMotion } = React.use(MotionConfigContext);
  return reducedMotion === 'always' ? 'always' : own;
}

type ReducedMotionConfigProps = {
  children: React.ReactNode;
  remount?: boolean;
};

function ReducedMotionConfig({ children, remount }: ReducedMotionConfigProps) {
  const reducedMotion = useReducedMotionSetting();

  return (
    <MotionConfig reducedMotion={reducedMotion}>
      {remount ? <RemountOnReduce>{children}</RemountOnReduce> : children}
    </MotionConfig>
  );
}

function RemountOnReduce({ children }: { children: React.ReactNode }) {
  const reduce = useShouldReduceMotion();
  return (
    <React.Fragment key={reduce ? 'reduce' : 'full'}>{children}</React.Fragment>
  );
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

function subscribeToReducedMotion(onChange: () => void) {
  const mql = window.matchMedia(REDUCED_MOTION_QUERY);
  mql.addEventListener('change', onChange);
  return () => mql.removeEventListener('change', onChange);
}

function useShouldReduceMotion() {
  const reducedMotion = useReducedMotionSetting();
  const prefersReduced = React.useSyncExternalStore(
    subscribeToReducedMotion,
    () => window.matchMedia(REDUCED_MOTION_QUERY).matches,
    () => false,
  );

  if (reducedMotion === 'never') return false;
  return reducedMotion === 'always' || prefersReduced;
}

